-- discrim-controle-conteste-motif-du-controle — C'est le troisieme controle cette semaine, toujours moi
SELECT public.fn_cp_import_case('discrim-controle-conteste-motif-du-controle', '{"slug": "discrim-controle-conteste-motif-du-controle", "title": "C''est le troisieme controle cette semaine, toujours moi", "theme_slug": "discriminations", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 17 heures. Vous controlez l''identite d''un jeune homme sur la voie publique, dans le cadre d''une mission de surveillance generale du secteur. Des les premiers mots, il conteste ce controle, affirmant que c''est la troisieme fois cette semaine qu''il est controle dans ce meme quartier, toujours lui parmi le groupe d''amis avec qui il se trouve a chaque fois. Il ne devient pas agressif mais exprime une lassitude et une amertume manifestes, estimant que ces controles repetes tiennent a son apparence plutot qu''a un motif objectif. Votre mission du jour repose sur des consignes generales de surveillance du secteur, sans element individualise le visant personnellement. Vous ne disposez d''aucun moyen immediat de verifier ses affirmations sur ces deux controles precedents.", "questions": [{"position": 1, "max_points": 5, "label": "Comment menez-vous ce controle tout en tenant compte du vecu qu''il exprime ?", "hint": "Le motif objectif du controle et le sentiment vecu par cette personne ne s''excluent pas mutuellement.", "perfect": "J''explique le motif objectif et ne balaye pas le vecu, ces deux elements pouvant etre tenus ensemble sans se contredire. Je reste factuelle sur le cadre de ma mission du jour, sans en faire une justification defensive face a sa contestation. J''ecoute ce qu''il exprime sur ces controles precedents sans le disqualifier, meme si je ne peux verifier ces faits sur le moment. Je conduis ce controle avec la meme courtoisie que j''appliquerais a toute autre personne, sans que sa contestation n''influence negativement mon attitude.", "points": [{"position": 1, "label": "Expliquer le motif objectif du controle et ne pas balayer le vecu exprime", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Poids fort du cas.", "groups": [{"position": 1, "keywords": ["motif explique", "vecu reconnu", "double exigence tenue"]}]}, {"position": 2, "label": "Rester factuelle sur le cadre de la mission sans posture defensive", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Explication sans defensive excessive.", "groups": [{"position": 1, "keywords": ["cadre explique", "posture factuelle", "defensive evitee"]}]}, {"position": 3, "label": "Ecouter ce qu''il exprime sur les controles precedents sans le disqualifier", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Ecoute du vecu sans verification possible.", "groups": [{"position": 1, "keywords": ["vecu ecoute", "disqualification evitee", "propos entendus"]}]}, {"position": 4, "label": "Conduire ce controle avec la meme courtoisie qu''a l''accoutumee", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Constance du traitement.", "groups": [{"position": 1, "keywords": ["courtoisie maintenue", "traitement constant", "attitude egale"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment gerez-vous la question de cette repetition qu''il allegue, sans pouvoir la verifier sur le moment ?", "hint": "L''impossibilite de verifier immediatement ne dispense pas de prendre cette allegation au serieux.", "perfect": "Je prends note de cette allegation de repetition, sans la confirmer ni la nier faute d''element de verification immediat. Je lui explique honnetement que je ne dispose pas des moyens de verifier ces controles precedents sur le terrain, sans pour autant balayer cette preoccupation. Je consigne cette situation dans mon compte rendu, cette information pouvant utilement alerter si une repetition anormale devait se confirmer. Je lui indique les voies existantes s''il souhaite formaliser une contestation de ces controles repetes.", "points": [{"position": 1, "label": "Prendre note sans confirmer ni nier faute de verification possible", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Prudence factuelle face a l''allegation.", "groups": [{"position": 1, "keywords": ["allegation notee", "verification impossible", "prudence maintenue"]}]}, {"position": 2, "label": "Expliquer honnetement l''impossibilite de verifier sur le terrain", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Transparence sur les limites.", "groups": [{"position": 1, "keywords": ["limites expliquees", "honnetete assuree", "verification impossible"]}]}, {"position": 3, "label": "Consigner cette situation dans le compte rendu", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Traçabilite utile en cas de repetition confirmee.", "groups": [{"position": 1, "keywords": ["situation consignee", "compte rendu complete", "alerte possible"]}]}, {"position": 4, "label": "Indiquer les voies existantes pour contester ces controles repetes", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Recours legitimes indiques.", "groups": [{"position": 1, "keywords": ["voies indiquees", "contestation possible", "recours explique"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment cloturez-vous ce controle une fois les verifications d''usage terminees ?", "hint": "La fin du controle est aussi l''occasion de ne pas laisser cette personne sur un sentiment d''injustice non entendue.", "perfect": "Je conclus ce controle en le remerciant de sa cooperation, comme je le ferais pour toute autre personne controlee dans ce cadre. Je reponds simplement, sans les balayer, aux dernieres remarques qu''il pourrait formuler sur ce vecu. Je ne cherche pas a le convaincre que son ressenti est infonde, cette question ne relevant pas de ce que je peux trancher sur le terrain. Je documente cette interaction de maniere factuelle, y compris le climat dans lequel ce controle s''est deroule.", "points": [{"position": 1, "label": "Conclure en le remerciant de sa cooperation comme pour toute personne", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Egalite de traitement jusqu''au bout.", "groups": [{"position": 1, "keywords": ["remerciement exprime", "cooperation reconnue", "egalite maintenue"]}]}, {"position": 2, "label": "Repondre simplement aux dernieres remarques sans les balayer", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Ecoute maintenue jusqu''a la fin.", "groups": [{"position": 1, "keywords": ["remarques entendues", "reponse donnee", "ecoute maintenue"]}]}, {"position": 3, "label": "Ne pas chercher a le convaincre que son ressenti est infonde", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Respect du ressenti exprime.", "groups": [{"position": 1, "keywords": ["ressenti respecte", "conviction non imposee", "jugement evite"]}]}, {"position": 4, "label": "Documenter factuellement le climat de cette interaction", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Traçabilite du climat.", "groups": [{"position": 1, "keywords": ["climat documente", "interaction decrite", "compte rendu complet"]}]}]}]}'::jsonb);

-- discrim-conflit-a-caractere-religieux-voisinage — Les degradations visent systematiquement la meme porte
SELECT public.fn_cp_import_case('discrim-conflit-a-caractere-religieux-voisinage', '{"slug": "discrim-conflit-a-caractere-religieux-voisinage", "title": "Les degradations visent systematiquement la meme porte", "theme_slug": "discriminations", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 19 heures. Une famille vous signale que la porte de son appartement, en copropriete, fait l''objet de degradations repetees depuis plusieurs semaines, des inscriptions et des salissures visant specifiquement leur porte alors qu''aucune autre porte du meme couloir n''est jamais touchee. La famille evoque une pratique religieuse visible qui pourrait expliquer ce ciblage, sans pouvoir designer d''auteur precis. Le syndic, contacte, minimise ces faits, les qualifiant de simples incivilites sans caractere particulier. Aucune camera ne couvre ce couloir interieur de l''immeuble. La famille, lasse de ces degradations repetees, hesite entre porter plainte formellement et simplement changer de porte pour ne plus y penser.", "questions": [{"position": 1, "max_points": 5, "label": "Comment documentez-vous le caractere cible et repete de ces degradations ?", "hint": "Une porte systematiquement visee parmi d''autres identiques raconte quelque chose que des faits isoles ne diraient pas.", "perfect": "Je documente le caractere cible et repete de ces faits, cette specificite restant l''element central pour distinguer une simple incivilite d''un ciblage discriminatoire. Je recueille precisement la chronologie de chaque degradation constatee, avec photos si possible a chaque occurrence. Je verifie aupres de la famille l''absence de degradation sur les autres portes du meme couloir, cette comparaison restant essentielle. Je ne presume pas le mobile religieux evoque par la famille, tout en le consignant comme element qu''elle rapporte.", "points": [{"position": 1, "label": "Documenter le caractere cible et repete de ces degradations", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Poids fort du cas.", "groups": [{"position": 1, "keywords": ["ciblage documente", "repetition etablie", "caractere specifique"]}]}, {"position": 2, "label": "Recueillir precisement la chronologie avec photos si possible", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Preuve materielle constituee.", "groups": [{"position": 1, "keywords": ["chronologie recueillie", "photos prises", "preuve constituee"]}]}, {"position": 3, "label": "Verifier l''absence de degradation sur les autres portes du couloir", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Comparaison etablissant le ciblage.", "groups": [{"position": 1, "keywords": ["autres portes verifiees", "comparaison effectuee", "ciblage confirme"]}]}, {"position": 4, "label": "Ne pas presumer le mobile religieux tout en le consignant", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Prudence sur la qualification du mobile.", "groups": [{"position": 1, "keywords": ["mobile consigne", "presomption evitee", "prudence maintenue"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment gerez-vous la minimisation de ces faits par le syndic ?", "hint": "Le syndic n''a pas la meme obligation d''analyse que vous face a ce type de signalement.", "perfect": "Je reste factuelle face au syndic sans accepter sa minimisation, la repetition et le ciblage constate meritant une attention que de simples incivilites n''appelleraient pas forcement. Je lui explique la difference entre une degradation isolee et ce ciblage repete que je constate dans le dossier. Je sollicite, malgre son scepticisme, sa collaboration pour d''eventuelles mesures preventives, comme l''installation d''une camera dans ce couloir. Je ne laisse pas cette minimisation influencer le traitement que je reserve a ce signalement.", "points": [{"position": 1, "label": "Ne pas accepter la minimisation du syndic face aux faits constates", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Independance du traitement policier.", "groups": [{"position": 1, "keywords": ["minimisation ecartee", "faits maintenus", "independance assuree"]}]}, {"position": 2, "label": "Expliquer la difference entre incivilite isolee et ciblage repete", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Pedagogie envers le syndic.", "groups": [{"position": 1, "keywords": ["difference expliquee", "ciblage clarifie", "pedagogie appliquee"]}]}, {"position": 3, "label": "Solliciter sa collaboration pour des mesures preventives", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Collaboration recherchee malgre le scepticisme.", "groups": [{"position": 1, "keywords": ["collaboration sollicitee", "camera proposee", "mesures preventives"]}]}, {"position": 4, "label": "Ne pas laisser cette minimisation influencer le traitement du signalement", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Independance maintenue.", "groups": [{"position": 1, "keywords": ["traitement maintenu", "influence ecartee", "independance affirmee"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment aidez-vous cette famille a choisir entre porter plainte et simplement changer de porte ?", "hint": "Cette famille lasse merite une information complete pour decider en connaissance de cause, sans que vous decidiez a sa place.", "perfect": "Je leur explique les consequences respectives de chacune de ces deux options, sans decider a leur place ce qu''ils doivent faire de cette situation. Je les informe que le dossier deja constitue reste valable meme s''ils choisissent d''attendre avant de porter plainte formellement. Je les oriente vers les associations specialisees en matiere de discrimination si un mobile religieux venait a se confirmer. Je reste attentive a leur lassitude legitime, sans pour autant les pousser vers une decision plutot qu''une autre.", "points": [{"position": 1, "label": "Expliquer les consequences de chaque option sans decider a leur place", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Information complete sans imposition.", "groups": [{"position": 1, "keywords": ["options expliquees", "decision respectee", "information complete"]}]}, {"position": 2, "label": "Informer que le dossier reste valable meme en cas d''attente", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Flexibilite temporelle expliquee.", "groups": [{"position": 1, "keywords": ["dossier valable", "attente possible", "flexibilite offerte"]}]}, {"position": 3, "label": "Orienter vers les associations specialisees en discrimination", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Ressources complementaires proposees.", "groups": [{"position": 1, "keywords": ["association orientee", "ressources proposees", "specialisation indiquee"]}]}, {"position": 4, "label": "Rester attentive a leur lassitude sans pousser vers une decision", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Neutralite dans l''accompagnement.", "groups": [{"position": 1, "keywords": ["lassitude reconnue", "neutralite maintenue", "decision libre"]}]}]}]}'::jsonb);

-- discrim-personne-transgenre-victime-agression — L'agresseur a filme la scene en la nommant par son ancien prenom
SELECT public.fn_cp_import_case('discrim-personne-transgenre-victime-agression', '{"slug": "discrim-personne-transgenre-victime-agression", "title": "L''agresseur a filme la scene en la nommant par son ancien prenom", "theme_slug": "discriminations", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 23 heures. Une femme transgenre vous signale avoir ete agressee physiquement dans la rue par un individu qui l''a filmee pendant les faits en la nommant a plusieurs reprises par son ancien prenom, celui figurant encore sur ses documents d''identite. Cette video, selon elle, circule deja sur les reseaux sociaux au moment ou elle vous parle. Elle presente des marques de coups visibles et reste tres marquee par cette double humiliation, l''agression physique et cette exposition publique sous une identite qu''elle ne reconnait plus comme la sienne. L''agresseur a pris la fuite apres les faits. Elle vous demande, avec insistance, d''etre appelee et designee tout au long de cette procedure par son prenom d''usage, et non celui figurant sur ses papiers.", "questions": [{"position": 1, "max_points": 5, "label": "Comment respectez-vous son identite tout au long de ce recueil ?", "hint": "Le respect de l''identite ne se limite pas a une formule polie, il traverse chaque echange de cette procedure.", "perfect": "Je respecte l''identite de la personne dans tout l''echange, l''appelant par son prenom d''usage comme elle le demande, y compris devant d''eventuels tiers presents. Je concilie cette exigence avec les mentions administratives qui, elles, doivent parfois correspondre a l''etat civil officiel, en le lui expliquant simplement. Je reste attentive a ne jamais utiliser son ancien prenom dans mes echanges directs avec elle, cette vigilance restant essentielle apres ce qu''elle vient de subir. Je verifie que les autres intervenants eventuels, secours ou collegues, respectent egalement cette demande.", "points": [{"position": 1, "label": "Respecter l''identite de la personne dans tout l''echange", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Poids fort du cas.", "groups": [{"position": 1, "keywords": ["identite respectee", "prenom d''usage employe", "echange adapte"]}]}, {"position": 2, "label": "Concilier cette exigence avec les mentions administratives necessaires", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Cadre administratif explique avec tact.", "groups": [{"position": 1, "keywords": ["mentions expliquees", "cadre administratif", "conciliation assuree"]}]}, {"position": 3, "label": "Ne jamais utiliser son ancien prenom dans les echanges directs", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Vigilance continue sur le respect de l''identite.", "groups": [{"position": 1, "keywords": ["ancien prenom evite", "vigilance maintenue", "respect continu"]}]}, {"position": 4, "label": "Verifier que les autres intervenants respectent aussi cette demande", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Coordination avec les autres services.", "groups": [{"position": 1, "keywords": ["intervenants informes", "coordination assuree", "respect etendu"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment traitez-vous la question de cette video diffusee, en plus de l''agression physique ?", "hint": "Cette diffusion constitue une atteinte distincte de l''agression elle-meme, avec ses propres consequences.", "perfect": "Je recueille precisement les elements permettant d''identifier cette video, plateforme, compte ayant publie, pour permettre une demarche de retrait et une exploitation judiciaire. J''explique que cette diffusion constitue une infraction distincte de l''agression physique, meritant une qualification propre dans la procedure. Je l''oriente vers les demarches possibles pour faire retirer ce contenu, sans lui garantir un delai que je ne maitrise pas. Je consigne ces elements numeriques avec la meme rigueur que les constatations physiques de cette agression.", "points": [{"position": 1, "label": "Recueillir les elements permettant d''identifier cette video", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Identification necessaire au retrait et a la procedure.", "groups": [{"position": 1, "keywords": ["video identifiee", "elements recueillis", "plateforme notee"]}]}, {"position": 2, "label": "Expliquer que cette diffusion constitue une infraction distincte", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Qualification propre a la diffusion.", "groups": [{"position": 1, "keywords": ["infraction distincte", "diffusion qualifiee", "explication donnee"]}]}, {"position": 3, "label": "Orienter vers les demarches de retrait sans garantir de delai", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Realisme sur les demarches possibles.", "groups": [{"position": 1, "keywords": ["retrait oriente", "demarches expliquees", "delai non garanti"]}]}, {"position": 4, "label": "Consigner ces elements numeriques avec la meme rigueur que les faits physiques", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Rigueur egale pour les deux volets.", "groups": [{"position": 1, "keywords": ["elements numeriques consignes", "rigueur egale", "dossier complet"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment accompagnez-vous cette femme face a cette double humiliation qu''elle vient de subir ?", "hint": "L''agression physique et l''exposition publique sous une identite rejetee constituent deux blessures distinctes.", "perfect": "Je m''assure qu''elle beneficie d''un examen medical adapte a ces marques de coups, cette prise en charge restant prioritaire. Je l''oriente vers des associations specialisees dans l''accompagnement des personnes transgenres victimes de violences, disposant d''un savoir-faire specifique sur cette double blessure. Je reste attentive a ne jamais minimiser l''impact de cette exposition publique, qui s''ajoute a l''agression elle-meme. Je lui indique comment suivre l''evolution de cette procedure dans le respect de son identite tout au long du parcours.", "points": [{"position": 1, "label": "S''assurer d''un examen medical adapte aux marques de coups", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Suivi medical prioritaire.", "groups": [{"position": 1, "keywords": ["examen medical", "coups constates", "soins organises"]}]}, {"position": 2, "label": "Orienter vers des associations specialisees pour personnes transgenres", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Accompagnement specialise necessaire.", "groups": [{"position": 1, "keywords": ["association orientee", "specialisation proposee", "accompagnement adapte"]}]}, {"position": 3, "label": "Ne jamais minimiser l''impact de cette exposition publique", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Reconnaissance de la double blessure.", "groups": [{"position": 1, "keywords": ["exposition reconnue", "impact non minimise", "double blessure admise"]}]}, {"position": 4, "label": "Indiquer comment suivre la procedure dans le respect de son identite", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Continuite du respect tout au long du suivi.", "groups": [{"position": 1, "keywords": ["suivi respectueux", "identite maintenue", "parcours explique"]}]}]}]}'::jsonb);

-- discrim-accusation-publique-visant-les-policiers — Une foule se forme, on vous accuse de racisme a voix haute
SELECT public.fn_cp_import_case('discrim-accusation-publique-visant-les-policiers', '{"slug": "discrim-accusation-publique-visant-les-policiers", "title": "Une foule se forme, on vous accuse de racisme a voix haute", "theme_slug": "discriminations", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 16 heures. Pendant que vous procedez a un controle de routine sur la voie publique, une foule commence a se former autour de vous, plusieurs personnes vous accusant a voix haute de racisme et filmant la scene avec leur telephone. Ces accusations, lancees sans que ces personnes n''aient assiste au debut de l''intervention, se fondent uniquement sur ce qu''elles observent depuis quelques instants. Votre binome, plus jeune, commence a hausser le ton en retour, visiblement affecte par ces accusations repetees. La personne controlee, elle, reste silencieuse pendant que cette foule s''exprime a sa place. La tension monte rapidement et le nombre de personnes autour de vous continue d''augmenter.", "questions": [{"position": 1, "max_points": 5, "label": "Comment maintenez-vous votre maitrise face a ces accusations publiques et filmees ?", "hint": "Une reaction emotionnelle, meme comprehensible, ne ferait que confirmer aux yeux de cette foule l''image qu''elle projette deja.", "perfect": "Je maintiens ma maitrise de soi et poursuis une action irreprochable, cette exigence restant d''autant plus importante que la scene est filmee et largement observee. Je ne reponds pas a ces accusations par de la colere ou de la defensive, meme si elles sont infondees et injustes. Je continue l''intervention en cours selon les regles habituelles, sans la precipiter ni la modifier a cause de cette pression exterieure. Je reste attentive a mon propre langage corporel, qui sera autant scrute que mes paroles par les personnes presentes.", "points": [{"position": 1, "label": "Maintenir sa maitrise de soi et poursuivre une action irreprochable", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Poids fort du cas.", "groups": [{"position": 1, "keywords": ["maitrise maintenue", "action irreprochable", "calme conserve"]}]}, {"position": 2, "label": "Ne pas repondre par de la colere ou de la defensive", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Reaction emotionnelle evitee.", "groups": [{"position": 1, "keywords": ["colere evitee", "defensive absente", "reaction maitrisee"]}]}, {"position": 3, "label": "Poursuivre l''intervention selon les regles habituelles sans la precipiter", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Regularite de l''action maintenue.", "groups": [{"position": 1, "keywords": ["intervention poursuivie", "regles respectees", "precipitation evitee"]}]}, {"position": 4, "label": "Rester attentive a son propre langage corporel", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Vigilance sur l''image projetee.", "groups": [{"position": 1, "keywords": ["langage corporel maitrise", "image consideree", "attitude soignee"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment gerez-vous votre binome, plus jeune, qui commence a hausser le ton face a ces accusations ?", "hint": "Un equipage divise face a une foule hostile aggrave considerablement la situation.", "perfect": "J''interviens discretement aupres de mon binome pour l''inviter au calme, sans le reprimander devant cette foule qui aggraverait son sentiment d''injustice. Je prends, si necessaire, le relais de la parole face a la foule pour desamorcer cet echange qui s''envenime. Je reste solidaire de lui dans mon attitude generale, sans le desavouer publiquement malgre ce ton qu''il a hausse. Je lui reparlerai de cette gestion emotionnelle une fois cette intervention terminee, dans un cadre plus calme.", "points": [{"position": 1, "label": "Intervenir discretement pour inviter son binome au calme", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Coordination de l''equipage face a la pression.", "groups": [{"position": 1, "keywords": ["binome invite au calme", "intervention discrete", "coordination assuree"]}]}, {"position": 2, "label": "Prendre le relais de la parole face a la foule si necessaire", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Desamorcage actif de l''echange.", "groups": [{"position": 1, "keywords": ["relais pris", "echange desamorce", "parole reprise"]}]}, {"position": 3, "label": "Rester solidaire sans desavouer publiquement son binome", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Solidarite d''equipage maintenue.", "groups": [{"position": 1, "keywords": ["solidarite maintenue", "desaveu evite", "equipage uni"]}]}, {"position": 4, "label": "Reparler de cette gestion emotionnelle dans un cadre calme ulterieur", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Retour pedagogique differe.", "groups": [{"position": 1, "keywords": ["retour prevu", "cadre calme", "gestion abordee ulterieurement"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment cloturez-vous cette intervention et en rendez-vous compte ensuite ?", "hint": "Une intervention filmee et contestee publiquement merite un compte rendu particulierement precis.", "perfect": "Je termine cette intervention selon la procedure normale, sans la precipiter pour echapper a cette pression de la foule. Je documente precisement le deroulement de ce controle et de ces accusations, y compris le fait que la scene ait ete filmee par plusieurs personnes. Je rends compte de cet incident a ma hierarchie sans en minimiser l''ampleur, cette transparence restant utile si ces images venaient a circuler ensuite. Je reste disponible pour expliquer, si necessaire, le deroule exact de cette intervention aupres des autorites competentes.", "points": [{"position": 1, "label": "Terminer l''intervention selon la procedure normale sans la precipiter", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Regularite maintenue jusqu''au bout.", "groups": [{"position": 1, "keywords": ["procedure normale", "precipitation evitee", "intervention terminee"]}]}, {"position": 2, "label": "Documenter precisement le deroulement y compris les prises de vue", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Traçabilite complete de l''incident.", "groups": [{"position": 1, "keywords": ["deroulement documente", "prises de vue notees", "compte rendu complet"]}]}, {"position": 3, "label": "Rendre compte a la hierarchie sans minimiser l''ampleur", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Transparence hierarchique.", "groups": [{"position": 1, "keywords": ["hierarchie informee", "ampleur reconnue", "transparence assuree"]}]}, {"position": 4, "label": "Rester disponible pour expliquer le deroule aux autorites competentes", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Disponibilite pour la suite.", "groups": [{"position": 1, "keywords": ["disponibilite maintenue", "explications offertes", "autorites informees"]}]}]}]}'::jsonb);

-- discrim-temoin-refuse-de-parler-raisons-culturelles — Il detourne le regard et dit que ca ne le concerne pas
SELECT public.fn_cp_import_case('discrim-temoin-refuse-de-parler-raisons-culturelles', '{"slug": "discrim-temoin-refuse-de-parler-raisons-culturelles", "title": "Il detourne le regard et dit que ca ne le concerne pas", "theme_slug": "discriminations", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 18 heures. Dans un quartier residentiel, vous enquetez sur un differend et sollicitez le temoignage d''un homme age qui a manifestement assiste a la scene depuis sa fenetre. Des que vous l''interrogez, il detourne le regard, repond de maniere evasive et affirme que cela ne le concerne pas, sans pour autant nier avoir vu quelque chose. Son attitude suggere une reticence liee davantage a une defiance envers les institutions ou a des codes sociaux particuliers qu''a une simple mauvaise volonte. Il ne se montre jamais hostile envers vous, seulement tres reserve. Le temps presse pour cette enquete, mais ce temoignage pourrait s''averer determinant pour etablir les faits.", "questions": [{"position": 1, "max_points": 5, "label": "Comment abordez-vous ce refus qui semble relever davantage d''une reticence culturelle que d''une hostilite ?", "hint": "Forcer ce temoignage risquerait de braquer definitivement cette personne, sans garantir sa fiabilite pour autant.", "perfect": "Je cherche a comprendre le refus sans le forcer ni le juger, cette reticence meritant d''etre entendue avant d''etre contournee. Je reste respectueuse de sa reserve, sans insister au point de le braquer davantage. Je lui explique simplement l''importance de son temoignage pour etablir les faits, sans exercer de pression excessive. J''observe s''il existe un moyen plus discret ou indirect de recueillir son temoignage, adapte a sa reticence.", "points": [{"position": 1, "label": "Chercher a comprendre le refus sans le forcer ni le juger", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Poids fort du cas.", "groups": [{"position": 1, "keywords": ["refus compris", "forcage evite", "jugement absent"]}]}, {"position": 2, "label": "Rester respectueuse de sa reserve sans le braquer", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Respect de sa posture.", "groups": [{"position": 1, "keywords": ["reserve respectee", "braquage evite", "posture menagee"]}]}, {"position": 3, "label": "Expliquer l''importance de son temoignage sans pression excessive", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Explication mesuree.", "groups": [{"position": 1, "keywords": ["importance expliquee", "pression mesuree", "temoignage valorise"]}]}, {"position": 4, "label": "Observer un moyen plus discret de recueillir ce temoignage", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Adaptation a sa reticence.", "groups": [{"position": 1, "keywords": ["moyen discret", "adaptation trouvee", "alternative envisagee"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment conciliez-vous cette approche respectueuse avec l''urgence de cette enquete ?", "hint": "Le temps qui presse ne justifie pas de sacrifier la qualite de ce recueil, mais impose de trouver un equilibre.", "perfect": "Je recueille les elements que je peux obtenir dans l''immediat, meme partiels, sans exiger une declaration complete sur le moment. Je lui laisse la possibilite de me recontacter ulterieurement s''il se sentait pret a en dire davantage. Je poursuis en parallele d''autres pistes d''enquete, sans faire reposer exclusivement le dossier sur ce seul temoignage reticent. Je consigne cette reticence et ses raisons supposees, cet element restant utile pour comprendre le dossier.", "points": [{"position": 1, "label": "Recueillir les elements possibles dans l''immediat sans exiger le complet", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Recueil partiel accepte.", "groups": [{"position": 1, "keywords": ["elements partiels", "recueil accepte", "declaration non exigee"]}]}, {"position": 2, "label": "Laisser la possibilite de le recontacter ulterieurement", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Ouverture pour un temoignage differe.", "groups": [{"position": 1, "keywords": ["recontact possible", "porte ouverte", "temoignage differe"]}]}, {"position": 3, "label": "Poursuivre d''autres pistes d''enquete en parallele", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Dossier non exclusivement dependant.", "groups": [{"position": 1, "keywords": ["autres pistes", "enquete diversifiee", "dependance evitee"]}]}, {"position": 4, "label": "Consigner cette reticence et ses raisons supposees", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Element utile pour comprendre le dossier.", "groups": [{"position": 1, "keywords": ["reticence consignee", "raisons notees", "dossier eclaire"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment cloturez-vous cet echange sans compromettre une eventuelle demarche future de sa part ?", "hint": "La maniere de partir compte autant que la maniere d''arriver, si vous souhaitez qu''il vous recontacte un jour.", "perfect": "Je le remercie du temps qu''il m''a accorde, meme sans temoignage complet obtenu, cette courtoisie restant importante pour l''avenir. Je lui laisse mes coordonnees de maniere simple, sans insister davantage sur cette demande. Je ne manifeste aucune frustration visible face a ce refus partiel, cette reaction pouvant compromettre toute demarche future de sa part. Je documente cet echange de maniere factuelle et respectueuse dans mon compte rendu.", "points": [{"position": 1, "label": "Le remercier du temps accorde meme sans temoignage complet", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Courtoisie preservant l''avenir.", "groups": [{"position": 1, "keywords": ["remerciement exprime", "courtoisie maintenue", "temps reconnu"]}]}, {"position": 2, "label": "Laisser ses coordonnees simplement sans insister davantage", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Ouverture sans pression.", "groups": [{"position": 1, "keywords": ["coordonnees laissees", "insistance evitee", "ouverture simple"]}]}, {"position": 3, "label": "Ne manifester aucune frustration visible face a ce refus partiel", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Maitrise emotionnelle maintenue.", "groups": [{"position": 1, "keywords": ["frustration absente", "maitrise maintenue", "reaction neutre"]}]}, {"position": 4, "label": "Documenter cet echange de maniere factuelle et respectueuse", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Compte rendu respectueux.", "groups": [{"position": 1, "keywords": ["echange documente", "respect maintenu", "compte rendu factuel"]}]}]}]}'::jsonb);

-- discrim-discrimination-embauche-signalee — Deux candidatures identiques, une seule a obtenu un entretien
SELECT public.fn_cp_import_case('discrim-discrimination-embauche-signalee', '{"slug": "discrim-discrimination-embauche-signalee", "title": "Deux candidatures identiques, une seule a obtenu un entretien", "theme_slug": "discriminations", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 11 heures. Au commissariat, une femme vous signale une discrimination a l''embauche : avec une amie, elle a envoye deux candidatures rigoureusement identiques en termes de qualifications et d''experience pour le meme poste, en ne modifiant que le nom du candidat. Seule la candidature portant un nom d''apparence occidentale a obtenu un entretien, l''autre n''ayant recu aucune reponse plusieurs semaines apres l''envoi. Elle vous presente les deux candidatures imprimees ainsi que les echanges de mail correspondants. Cet element de comparaison est interessant mais la preuve d''une intention discriminatoire reste, comme souvent en cette matiere, difficile a etablir avec certitude a partir de ce seul testing informel.", "questions": [{"position": 1, "max_points": 5, "label": "Comment evaluez-vous la valeur de cet element de comparaison qu''elle vous presente ?", "hint": "Un testing informel n''a pas la meme rigueur qu''un testing officiel, mais n''est pas pour autant sans valeur.", "perfect": "Je recueille les elements comparatifs sans conclure prematurement sur l''intention de l''employeur, cette prudence restant necessaire face a un testing mene de maniere informelle. J''examine attentivement les deux candidatures pour verifier qu''elles sont effectivement en tout point comparables, hormis le nom. Je note precisement les dates d''envoi et de reponse pour etablir une chronologie exploitable. Je reste factuelle dans mon appreciation, sans presenter cet element comme une preuve definitive a ce stade.", "points": [{"position": 1, "label": "Recueillir les elements comparatifs sans conclure prematurement", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Poids fort du cas.", "groups": [{"position": 1, "keywords": ["elements recueillis", "conclusion differee", "comparaison etablie"]}]}, {"position": 2, "label": "Examiner que les deux candidatures sont bien comparables en tout point", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Rigueur de la comparaison.", "groups": [{"position": 1, "keywords": ["candidatures comparees", "comparabilite verifiee", "rigueur assuree"]}]}, {"position": 3, "label": "Noter precisement les dates d''envoi et de reponse", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Chronologie exploitable etablie.", "groups": [{"position": 1, "keywords": ["dates notees", "chronologie etablie", "elements precis"]}]}, {"position": 4, "label": "Rester factuelle sans presenter cet element comme une preuve definitive", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Prudence sur la portee de la preuve.", "groups": [{"position": 1, "keywords": ["prudence maintenue", "preuve relativisee", "appreciation factuelle"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment recueillez-vous cette plainte pour maximiser ses chances d''aboutir malgre cette fragilite probatoire ?", "hint": "Un dossier bien construit peut compenser en partie la fragilite intrinseque d''un testing informel.", "perfect": "Je joins a la plainte l''ensemble des pieces qu''elle presente, candidatures imprimees et echanges de mail, sans en omettre aucune. Je recueille sa version precise des faits, y compris la maniere dont ce testing a ete organise avec son amie. Je l''interroge sur d''eventuels autres elements de contexte pouvant renforcer ce dossier, comme des retours anterieurs similaires de cette meme entreprise. Je transmets ce dossier aux autorites competentes en matiere de discrimination professionnelle pour une appreciation approfondie.", "points": [{"position": 1, "label": "Joindre l''ensemble des pieces presentees sans en omettre aucune", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Dossier complet constitue.", "groups": [{"position": 1, "keywords": ["pieces jointes", "dossier complet", "candidatures integrees"]}]}, {"position": 2, "label": "Recueillir sa version precise sur l''organisation de ce testing", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Contexte de constitution de la preuve.", "groups": [{"position": 1, "keywords": ["version recueillie", "testing explique", "organisation precisee"]}]}, {"position": 3, "label": "Interroger sur d''autres elements de contexte renforcant le dossier", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Renforcement du dossier recherche.", "groups": [{"position": 1, "keywords": ["contexte recherche", "elements complementaires", "dossier renforce"]}]}, {"position": 4, "label": "Transmettre ce dossier aux autorites competentes en discrimination professionnelle", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Orientation vers l''instance appropriee.", "groups": [{"position": 1, "keywords": ["dossier transmis", "autorites saisies", "instance appropriee"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment expliquez-vous a cette femme les suites realistes de cette demarche ?", "hint": "L''honnetete sur les difficultes probatoires vaut mieux qu''un faux espoir qui se transformerait en deception.", "perfect": "Je lui explique honnetement les difficultes probatoires propres a ce type de dossier, sans pour autant decourager sa demarche legitime. Je precise que cette plainte sera neanmoins recueillie et transmise, meme si son issue reste incertaine a ce stade. Je l''oriente vers des associations specialisees disposant parfois de methodologies de testing plus rigoureuses pour appuyer ce type de dossier. Je reste disponible pour recueillir tout element complementaire qu''elle pourrait obtenir par la suite.", "points": [{"position": 1, "label": "Expliquer honnetement les difficultes probatoires de ce type de dossier", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Honnetete sur la realite procedurale.", "groups": [{"position": 1, "keywords": ["difficultes expliquees", "honnetete assuree", "realite exposee"]}]}, {"position": 2, "label": "Preciser que la plainte sera neanmoins recueillie et transmise", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Demarche non decouragee.", "groups": [{"position": 1, "keywords": ["plainte recueillie", "transmission assuree", "demarche maintenue"]}]}, {"position": 3, "label": "Orienter vers des associations disposant de methodologies plus rigoureuses", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Ressources specialisees proposees.", "groups": [{"position": 1, "keywords": ["association orientee", "methodologie proposee", "ressources indiquees"]}]}, {"position": 4, "label": "Rester disponible pour tout element complementaire ulterieur", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Suivi ouvert pour la suite.", "groups": [{"position": 1, "keywords": ["disponibilite maintenue", "complement possible", "suivi ouvert"]}]}]}]}'::jsonb);

COMMIT;
